mapper.select:
select
t.MESSAGE_ID,
t.USER_ID,
t.VIEWED,
t.VIEWED_TIME,
t.ID,
t.CREATE_BY,
t.CREATE_TIME,
t.UPDATE_BY,
t.UPDATE_TIME,
a.TYPE,
a.TITLE,
a.CONTENT
from VT_MESSAGE_RECEIVER t
left join VT_MESSAGE a on a.ID = t.MESSAGE_ID


        and t.ID = #{p.id}


        and t.CREATE_BY = #{p.createBy}


        and t.CREATE_TIME = #{p.createTime}


        and t.UPDATE_BY = #{p.updateBy}


        and t.UPDATE_TIME = #{p.updateTime}


        and t.MESSAGE_ID = #{p.messageId}


        and t.USER_ID = #{p.userId}


        and t.VIEWED = #{p.viewed}


        and t.VIEWED_TIME = #{p.viewedTime}



        and a.TYPE = #{p.type}


        and a.TITLE like concat(concat('%', #{p.title}), '%')


        and a.CONTENT like concat(concat('%', #{p.content}), '%')


order by t.CREATE_TIME desc
